style.css:
@-moz-document domain("roblox.com") {
/* Global Reset and Base Styles */
    * {
        transition: all 0.3s ease-in-out; /* Smooth transitions for all elements */
        box-sizing: border-box;
    }

    /* Main Body and Background */
    body, html {
        background-color: #000000 !important; /* Pitch black background */
        color: #ffffff !important; /* Bright white text */
        font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
    }

    /* Navigation Bar */
    #navigation-container, .nav-container, .navbar {
        background-color: #0a0a0a !important; /* Slightly lighter black for depth */
        border-bottom: 1px solid #1c1c1c !important;
    }

    .nav, .nav-item, .nav-link, .navbar-brand {
        color: #ffffff !important;
        text-shadow: 0 0 5px rgba(255, 255, 255, 0.2);
    }

    .nav-link:hover, .navbar-brand:hover {
        color: #e0e0e0 !important;
        transform: scale(1.05); /* Subtle hover animation */
    }

    /* Buttons */
    .btn, .btn-primary, .btn-secondary, .btn-cta {
        background-color: #000000 !important;
        border: 1px solid #ffffff !important;
        color: #ffffff !important;
        border-radius: 8px;
        box-shadow: 0 0 10px rgba(255, 255, 255, 0.1);
    }

    .btn:hover {
        background-color: #1c1c1c !important;
        transform: translateY(-2px); /* Lift effect on hover */
        box-shadow: 0 5px 15px rgba(255, 255, 255, 0.3);
    }

    /* Cards and Containers */
    .game-card, .item-card, .thumbnail-2d-container, .card, .container-main {
        background-color: #0a0a0a !important;
        border: 1px solid #1c1c1c !important;
        border-radius: 10px;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5);
    }

    .game-card:hover, .item-card:hover {
        transform: translateY(-5px); /* Card lift on hover */
        box-shadow: 0 8px 20px rgba(255, 255, 255, 0.2);
    }

    /* Text and Headings */
    h1, h2, h3, h4, h5, h6, p, span, div, a {
        color: #ffffff !important;
    }

    .text-primary, .text-secondary, .text-info {
        color: #e0e0e0 !important;
    }

    /* Inputs and Forms */
    input, textarea, select, .form-control {
        background-color: #0a0a0a !important;
        border: 1px solid #1c1c1c !important;
        color: #ffffff !important;
        border-radius: 5px;
        padding: 10px;
    }

    input:focus, textarea:focus, select:focus {
        border-color: #ffffff !important;
        box-shadow: 0 0 8px rgba(255, 255, 255, 0.3);
        outline: none;
    }

    /* Icons and Images */
    .icon, .img, img:not(.avatar) {
        filter: brightness(1.2) contrast(1.1); /* Enhance visibility */
        transition: filter 0.3s ease;
    }

    .icon:hover, .img:hover {
        filter: brightness(1.5) contrast(1.2);
    }

    /* Chat and Social Sections */
    .chat-container, .people-list, .friend-carousel {
        background-color: #0a0a0a !important;
        border: 1px solid #1c1c1c !important;
    }

    .chat-message, .chat-input {
        color: #ffffff !important;
    }

    /* Footer */
    .footer, .footer-container {
        background-color: #000000 !important;
        border-top: 1px solid #1c1c1c !important;
        color: #ffffff !important;
    }

    /* Modals and Popups */
    .modal-content, .popover, .tooltip {
        background-color: #0a0a0a !important;
        color: #ffffff !important;
        border: 1px solid #1c1c1c !important;
        border-radius: 10px;
    }

    .modal-header, .modal-footer {
        border-color: #1c1c1c !important;
    }

    /* Scrollbars */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #000000;
    }

    ::-webkit-scrollbar-thumb {
        background: #ffffff;
        border-radius: 5px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #e0e0e0;
    }

    /* Animations for Loading */
    @keyframes fadeIn {
        from { opacity: 0; }
        to { opacity: 1; }
    }

    .game-card, .item-card, .container-main {
        animation: fadeIn 0.5s ease-in-out;
    }

    /* Ensure Avatars and Thumbnails Retain Original Colors */
    .avatar, .thumbnail-2d-container img, .game-tile img {
        filter: none !important;
    }
}
